@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Unbounded:wght@400;500;600;700&display=swap');
:root{--bg:#101114;--panel:#191a1f;--panel2:#202127;--line:#34353d;--muted:#9a9ba5;--text:#f4f0e9;--gold:#e5b968;--red:#e46d63;--green:#78bd91;--blue:#77b7d1;--purple:#b99be6}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% -20%,#2a2520 0,#171719 40%,#101114 75%);color:var(--text);font-family:'DM Sans',sans-serif;min-height:100vh}.grain{position:fixed;inset:0;pointer-events:none;opacity:.035;z-index:10;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E")}
button{font:inherit;color:inherit;cursor:pointer}#app{min-height:100vh}.screen{min-height:100vh;position:relative;padding:38px 5vw 46px;max-width:1600px;margin:auto}.eyebrow{font-size:10px;font-weight:700;letter-spacing:.24em;text-transform:uppercase;color:var(--gold)}.brand{font-family:Unbounded,sans-serif;letter-spacing:.12em;font-size:12px;color:#c9c4ba}.brand span{color:var(--gold)}.hero-head{text-align:center;margin:68px auto 42px}.hero-head h1{font-family:Unbounded,sans-serif;font-size:clamp(38px,6vw,78px);letter-spacing:-.07em;line-height:1.04;margin:17px 0 16px;font-weight:500}.hero-head h1 em{font-style:normal;color:var(--gold)}.hero-head p{color:#aaa9a5;font-size:15px;max-width:490px;margin:0 auto;line-height:1.7}.hero-select{max-width:1200px;margin:auto}.select-label{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;color:#c7c3bb;font-size:12px;letter-spacing:.1em;text-transform:uppercase}.select-label small{color:#777984;letter-spacing:0;text-transform:none;font-size:11px}.hero-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:13px}.hero-card{position:relative;text-align:left;border:1px solid #36353a;background:linear-gradient(150deg,#242329,#17181c 68%);border-radius:8px;min-height:310px;padding:20px 17px 16px;transition:.2s;overflow:hidden}.hero-card:before{content:'';position:absolute;inset:0;background:radial-gradient(circle at 75% 15%,var(--glow),transparent 55%);opacity:.11;transition:.2s}.hero-card:hover,.hero-card.selected{border-color:var(--accent);transform:translateY(-4px);box-shadow:0 12px 35px #0005}.hero-card:hover:before,.hero-card.selected:before{opacity:.23}.hero-icon{width:53px;height:53px;display:grid;place-items:center;font-size:27px;border:1px solid color-mix(in srgb,var(--accent),transparent 55%);border-radius:50%;background:#151519;margin-bottom:21px;box-shadow:0 0 24px color-mix(in srgb,var(--accent),transparent 83%)}.hero-card h2{font-family:Unbounded,sans-serif;font-size:14px;letter-spacing:-.04em;margin:0 0 5px}.hero-title{color:var(--accent);font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.hero-desc{color:#a7a5a8;font-size:11px;line-height:1.55;min-height:52px;margin:12px 0 15px}.perk-count{font-size:9px;color:#83828b;text-transform:uppercase;letter-spacing:.14em;padding-bottom:7px;border-bottom:1px solid #38373d;margin-bottom:8px}.perk-mini{font-size:10px;display:flex;gap:7px;line-height:1.45;color:#d4d0c7;margin-top:6px}.perk-mini b{color:var(--accent);font-size:11px}.hero-footer{display:flex;align-items:center;justify-content:space-between;margin:24px auto 0;max-width:1200px}.hero-footer .hint{color:#7d7e87;font-size:11px}.primary-btn,.subtle-btn{border:0;border-radius:4px;padding:13px 22px;background:var(--gold);color:#171513;font-weight:700;font-size:11px;letter-spacing:.1em;text-transform:uppercase;transition:.18s}.primary-btn:hover{background:#f0cc82;transform:translateY(-1px)}.primary-btn:disabled{opacity:.38;cursor:not-allowed;transform:none}.subtle-btn{background:transparent;color:#c4c0b9;border:1px solid #49484b}.subtle-btn:hover{border-color:var(--gold);color:var(--gold)}
/* combat */
.game-screen{padding:24px clamp(16px,4vw,58px) 25px;min-height:100vh;display:flex;flex-direction:column;max-width:1600px;margin:auto}.topbar{height:39px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #2e2f34;padding-bottom:15px}.topbar-left{display:flex;align-items:center;gap:23px}.run-name{font-family:Unbounded,sans-serif;font-size:10px;letter-spacing:.14em;color:#d4d0c9}.run-name span{color:var(--gold)}.act-label{font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#999aa2}.top-actions{display:flex;gap:9px}.tiny-btn{border:1px solid #3c3d43;background:#1a1b20;border-radius:4px;padding:7px 10px;color:#aaa;font-size:10px}.tiny-btn:hover{color:var(--gold);border-color:#9c7945}.combat-layout{flex:1;display:grid;grid-template-columns:minmax(0,1fr) 238px;gap:23px;max-width:1320px;width:100%;margin:23px auto 0;min-height:0}.battle-main{display:flex;flex-direction:column;min-width:0}.battle-title{display:flex;align-items:center;justify-content:center;gap:12px;margin:0 auto 15px;color:#a6a4aa;font-size:10px;text-transform:uppercase;letter-spacing:.16em}.battle-title:before,.battle-title:after{content:'';height:1px;width:50px;background:#46454a}.battle-title strong{color:var(--gold);font-weight:600}.stage{height:clamp(195px,29vh,275px);position:relative;border:1px solid #292a30;border-radius:7px;background:radial-gradient(ellipse at 50% 70%,#342b25 0,#222124 43%,#191a1e 76%);overflow:hidden;display:flex;align-items:center;justify-content:center}.stage:after{content:'';position:absolute;left:8%;right:8%;bottom:16%;height:1px;background:linear-gradient(90deg,transparent,#75644c,#75644c,transparent);box-shadow:0 0 30px #c7985244}.stage-glow{position:absolute;width:380px;height:180px;border-radius:50%;background:radial-gradient(ellipse,#ad75412a,transparent 70%);bottom:3%;filter:blur(8px)}.enemy-wrap{position:relative;z-index:2;text-align:center;transition:.2s}.enemy-wrap.hit{animation:hit .28s}@keyframes hit{25%{transform:translateX(-8px);filter:brightness(2)}75%{transform:translateX(6px)}}.enemy-emoji{font-size:83px;line-height:1;filter:drop-shadow(0 10px 11px #0008);margin:0 0 8px}.enemy-name{font-family:Unbounded,sans-serif;font-size:12px;letter-spacing:.02em}.enemy-sub{font-size:9px;color:#a7a3a0;margin-top:4px}.enemy-bar-wrap{width:190px;margin:13px auto 0}.health-meta{display:flex;justify-content:space-between;font-size:9px;color:#ddd;margin-bottom:5px}.health-track{height:5px;background:#40383a;border-radius:5px;overflow:hidden}.health-fill{height:100%;background:linear-gradient(90deg,#c44d49,#ee786a);transition:width .3s}.intent{display:inline-flex;align-items:center;gap:5px;background:#27272c;border:1px solid #49464a;border-radius:20px;padding:5px 10px;margin-top:10px;font-size:9px;color:#e4c487}.combat-status{display:flex;align-items:center;justify-content:center;gap:8px;min-height:38px}.status-chip{font-size:9px;color:#b9d7e3;background:#263137;border:1px solid #42535b;border-radius:12px;padding:4px 8px}.status-chip.gold{background:#332c20;border-color:#554832;color:#ebc77f}.status-chip.green{background:#203127;border-color:#3b5c45;color:#9dddac}.floor-label{text-align:center;color:#6d6f78;font-size:9px;text-transform:uppercase;letter-spacing:.15em;margin:2px 0 8px}.hero-row{display:flex;align-items:flex-end;justify-content:center;gap:24px;min-height:71px;margin-bottom:8px}.hero-portrait{height:61px;width:61px;border:1px solid var(--hero-color);border-radius:50%;background:radial-gradient(circle at 40% 25%,color-mix(in srgb,var(--hero-color),#242329 65%),#15161a 75%);display:grid;place-items:center;font-size:31px;position:relative;box-shadow:0 0 22px color-mix(in srgb,var(--hero-color),transparent 86%)}.hero-portrait .portrait-hp{position:absolute;right:-12px;bottom:-4px;background:#17171a;border:1px solid #3f3d3f;border-radius:9px;padding:3px 6px;font-size:9px;color:#eab7a9;white-space:nowrap}.player-stats{display:flex;gap:8px}.stat-pill{background:#1c1d21;border:1px solid #393a40;border-radius:4px;padding:7px 10px;min-width:58px;text-align:center}.stat-pill b{display:block;color:#ede4d2;font-size:13px}.stat-pill span{font-size:8px;color:#85868e;text-transform:uppercase;letter-spacing:.1em}.turn-row{display:flex;align-items:center;justify-content:space-between;margin:3px 0 8px}.energy-label{display:flex;align-items:center;gap:6px;color:#d9bd7a;font-size:10px}.energy-orbs{display:flex;gap:4px}.orb{width:10px;height:10px;border-radius:50%;border:1px solid #bca767;background:#d6b866;box-shadow:0 0 8px #c5a54e77}.orb.empty{background:#313139;border-color:#57575e;box-shadow:none}.end-turn{padding:9px 16px}.hand{display:flex;align-items:stretch;justify-content:center;gap:clamp(6px,1vw,13px);min-height:204px;padding:4px 2px 0;flex:0 0 auto}.card{width:clamp(118px,13.2vw,164px);height:194px;flex-shrink:0;border-radius:7px;border:1px solid #67605a;background:linear-gradient(160deg,#363237,#242328 52%,#1b1b20);position:relative;padding:0 12px 12px;display:flex;flex-direction:column;transition:transform .18s,border-color .18s,filter .18s;box-shadow:0 8px 14px #0004;overflow:hidden;cursor:pointer}.card:hover:not(.disabled){transform:translateY(-9px);border-color:var(--card-accent);z-index:3;box-shadow:0 12px 25px #0008}.card.disabled{filter:grayscale(.45) brightness(.68);cursor:not-allowed}.card:before{position:absolute;content:'';top:0;left:0;right:0;height:3px;background:var(--card-accent)}.card-top{display:flex;justify-content:space-between;align-items:center;padding-top:10px}.cost{height:26px;width:26px;display:grid;place-items:center;border-radius:50%;background:#253a44;border:1px solid #57717a;color:#c5e1e9;font-weight:700;font-size:12px}.card-type{font-size:8px;text-transform:uppercase;letter-spacing:.14em;color:#a5a1a0}.card-art{height:68px;display:grid;place-items:center;font-size:38px;position:relative}.card-art:after{content:'';position:absolute;bottom:2px;width:80%;height:1px;background:linear-gradient(90deg,transparent,var(--card-accent),transparent);opacity:.5}.card h3{margin:7px 0 5px;font-family:Unbounded,sans-serif;font-size:10px;letter-spacing:-.02em;color:#f1e8dc}.card-desc{font-size:9px;line-height:1.45;color:#aeabb0;flex:1}.card-desc b{color:#ead3a0}.card-tag{position:absolute;right:8px;bottom:7px;color:#77767e;font-size:7px;text-transform:uppercase;letter-spacing:.1em}.sidebar{border:1px solid #2e2f35;border-radius:6px;background:#18191d;display:flex;flex-direction:column;overflow:hidden;max-height:calc(100vh - 105px)}.side-section{padding:16px;border-bottom:1px solid #2c2d33}.side-heading{font-size:9px;color:#8f9098;text-transform:uppercase;letter-spacing:.16em;display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.side-heading span{color:var(--gold);font-size:9px}.player-panel{display:flex;gap:10px;align-items:center}.side-avatar{font-size:25px;height:42px;width:42px;display:grid;place-items:center;border:1px solid var(--hero-color);background:#222127;border-radius:5px}.side-name{font-size:11px;font-weight:700}.side-class{font-size:9px;color:#9e9aa1;margin-top:4px}.side-hp{margin-top:11px}.side-hp .health-track{height:4px}.side-hp-meta{display:flex;justify-content:space-between;font-size:9px;color:#c9c2b9;margin-bottom:5px}.perk-list{display:flex;flex-direction:column;gap:9px}.perk-row{display:flex;gap:9px;align-items:flex-start}.perk-gem{height:20px;width:20px;border-radius:50%;border:1px solid color-mix(in srgb,var(--hero-color),transparent 45%);color:var(--hero-color);display:grid;place-items:center;font-size:10px;flex:0 0 auto}.perk-copy b{font-size:9px;display:block;color:#e5dfd4;margin:0 0 3px}.perk-copy span{font-size:8px;line-height:1.35;color:#85858e;display:block}.deck-list{display:flex;flex-direction:column;gap:9px}.deck-item{display:flex;align-items:center;gap:8px;font-size:9px;color:#b0adb2}.deck-item i{font-style:normal;font-size:13px;width:19px;text-align:center}.deck-item span{margin-left:auto;color:#767780}.relics{display:flex;gap:7px}.relic{width:34px;height:34px;display:grid;place-items:center;border:1px solid #3a3b40;border-radius:4px;background:#222329;font-size:15px;position:relative}.relic:hover:after{content:attr(data-tip);position:absolute;bottom:40px;left:0;width:150px;padding:8px;background:#101114;border:1px solid #555;color:#ddd;font-size:9px;z-index:8;border-radius:4px}.combat-log{margin-top:auto;min-height:80px;padding:12px 15px;overflow:auto;max-height:125px}.log-line{font-size:8px;color:#82838b;line-height:1.5;margin:3px 0}.log-line:first-child{color:#d6c18d}.toast{position:fixed;left:50%;top:20%;transform:translate(-50%,-10px);opacity:0;pointer-events:none;background:#d6b86e;color:#171514;padding:10px 17px;border-radius:4px;font-size:11px;font-weight:700;letter-spacing:.04em;transition:.25s;z-index:30}.toast.show{transform:translate(-50%,0);opacity:1}.overlay{position:fixed;inset:0;z-index:20;background:#0b0c0edb;display:grid;place-items:center;padding:20px;backdrop-filter:blur(7px)}.modal{width:min(720px,100%);background:linear-gradient(145deg,#242329,#17181d);border:1px solid #48444a;border-radius:8px;padding:28px;box-shadow:0 25px 80px #000a}.modal-head{text-align:center;margin-bottom:22px}.modal-head .eyebrow{font-size:9px}.modal-head h2{font-family:Unbounded,sans-serif;font-size:24px;margin:10px 0 7px}.modal-head p{color:#9999a1;font-size:11px;margin:0}.reward-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.reward-grid .card{width:100%;height:206px}.modal-foot{display:flex;justify-content:space-between;align-items:center;margin-top:20px;color:#8f9097;font-size:10px}.reward-skip{border:0;background:transparent;color:#aaa;text-decoration:underline;font-size:10px;padding:8px}.result-icon{font-size:46px;text-align:center}.result-actions{text-align:center;margin-top:20px}.perks-modal{max-width:610px}.perk-detail{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.perk-tile{border:1px solid #3b3b42;border-radius:5px;padding:13px;background:#1a1b20}.perk-tile .perk-gem{margin-bottom:9px;width:25px;height:25px}.perk-tile b{font-size:10px;display:block;margin-bottom:5px}.perk-tile p{margin:0;color:#96969e;font-size:9px;line-height:1.5}
@media(max-width:980px){.hero-grid{grid-template-columns:repeat(3,1fr)}.hero-card{min-height:280px}.combat-layout{grid-template-columns:1fr}.sidebar{display:none}.stage{height:240px}.game-screen{padding:18px 16px}.hand{overflow-x:auto;justify-content:flex-start;padding:8px 6px 12px;min-height:215px}.card{width:148px;height:190px}.hero-row{margin-top:3px}}
