 guard:{name:'Quick Guard',cost:1,type:'Skill',icon:'🛡️',accent:'#c9b894',desc:'Gain <b>6 Block</b>.',block:6},meditate:{name:'Focus',cost:0,type:'Skill',icon:'🧘',accent:'#d0b97d',desc:'Draw 1 card.',draw:1},surge:{name:'Surge',cost:1,type:'Attack',icon:'✴️',accent:'#d0b97d',desc:'Deal <b>6</b> damage.',damage:6}
};
const ENEMIES=[
 {name:'Ashen Marauder',kind:'Wasteland Raider',icon:'🪓',hp:43,pattern:[['attack',8],['attack',10],['guard',7],['attack',12]]},
 {name:'Bog Warden',kind:'Guardian of the Fen',icon:'🐸',hp:59,pattern:[['attack',9],['buff',3],['attack',12],['attack',8]]},
 {name:'The Hollow King',kind:'Forgotten Sovereign · BOSS',icon:'👑',hp:88,boss:true,pattern:[['attack',12],['buff',4],['attack',16],['attack',10],['guard',12]]}
];
const app=document.getElementById('app');let selectedHero=null,run=null,toastTimer;
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showToast(text){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.appendChild(el)}el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1250)}
function heroSelect(){selectedHero=selectedHero||HEROES[0].id;app.innerHTML=`<main class="screen"><div class="brand"><span>MYTHOS</span> &nbsp; / &nbsp; THE SHATTERED REALMS</div><header class="hero-head"><div class="eyebrow">A roguelike deckbuilding journey</div><h1>Legends are<br><em>forged in battle.</em></h1><p>Choose your champion. Master their gifts. Fight through the Shattered Realms and end the Hollow King’s reign.</p></header><section class="hero-select"><div class="select-label"><span>Choose your champion</span><small>Every legend carries three unique perks</small></div><div class="hero-grid">${HEROES.map(h=>`<button class="hero-card ${h.id===selectedHero?'selected':''}" data-hero="${h.id}" style="--accent:${h.color};--glow:${h.color}"><div class="hero-icon">${h.icon}</div><h2>${h.name}</h2><div class="hero-title">${h.title}</div><p class="hero-desc">${h.desc}</p><div class="perk-count">✧ &nbsp; 3 signature perks</div>${h.perks.map((p,i)=>`<div class="perk-mini"><b>${p[0]}</b><span>${p[1]}</span></div>`).join('')}</button>`).join('')}</div><div class="hero-footer"><span class="hint">Your journey has three encounters. Defeat the Hollow King to win.</span><button class="primary-btn" data-action="start">Begin your journey&nbsp; →</button></div></section></main>`}
function startRun(){const hero=HEROES.find(h=>h.id===selectedHero);run={hero,hp:70,maxHp:70,deck:hero.deck.map(id=>({id})),discard:[],drawPile:[],hand:[],energy:3,block:0,strength:0,turn:1,act:1,enemy:null,enemyBlock:0,enemyStrength:0,enemyStep:0,log:[],status:'combat',used:{},cardsPlayed:0,attackCount:0,blocksGained:0,unlocked:{},victories:0};startCombat();renderGame()}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function addLog(t){run.log.unshift(t);run.log=run.log.slice(0,12)}
function startCombat(){const e=ENEMIES[run.act-1];run.enemy={...e,hp:e.hp,maxHp:e.hp};run.enemyBlock=0;run.enemyStrength=0;run.enemyStep=0;run.turn=1;run.strength=0;run.block=0;run.used={};run.cardsPlayed=0;run.attackCount=0;run.blocksGained=0;run.discard=[];run.hand=[];run.drawPile=shuffle(run.deck.map(c=>({...c})));run.energy=3;addLog(`${e.name} emerges from the gloom.`);startTurn(true)}
function drawCards(n){for(let i=0;i<n;i++){if(!run.drawPile.length&&run.discard.length)run.drawPile=shuffle(run.discard.splice(0));if(run.drawPile.length)run.hand.push(run.drawPile.pop())}}
function gainBlock(amount){if(amount<=0)return;let val=amount;if(run.hero.id==='tide'&&!run.used.tideguard){val+=3;run.used.tideguard=true;addLog('Tideguard adds 3 Block.')}run.block+=val;run.blocksGained++;addLog(`You gain ${val} Block.`);if(run.hero.id==='war'&&!run.used.counter){run.used.counter=true;dealDamage(2,false,'Counterstrike')}}
function startTurn(first=false){if(run.status!=='combat')return;run.block=0;run.energy=3;run.used={};if(run.hero.id==='necro')gainBlock(4);if(run.hero.id==='rebel'&&run.turn%2===0){run.energy++;addLog('Rally the People: +1 Energy.')}drawCards(run.hero.id==='monkey'&&first?6:5);addLog(`Turn ${run.turn} begins.`);renderGame()}
function dealDamage(amount,withBonus=true,label=''){let total=amount;if(withBonus){if(run.hero.id==='war'&&!run.used.ironwill){total+=3;run.used.ironwill=true;addLog('Iron Will adds 3 damage.')}if(run.hero.id==='rebel'&&run.hp<=run.maxHp/2)total+=2;total+=run.strength;if(run.hero.id==='monkey'&&run.attackCount%3===2){total+=5;addLog('Staff Rhythm adds 5 damage.')}}let blocked=Math.min(run.enemyBlock,total);run.enemyBlock-=blocked;let dealt=total-blocked;run.enemy.hp=Math.max(0,run.enemy.hp-dealt);if(label)addLog(label);addLog(`You deal ${dealt}${blocked?` (${blocked} blocked)`:''} damage.`);if(run.hero.id==='necro'&&withBonus&&dealt>0){const heal=Math.max(1,Math.floor(dealt/3));run.hp=Math.min(run.maxHp,run.hp+heal)}return dealt}
function playCard(index){if(run.status!=='combat')return;const c=run.hand[index],d=CARDS[c.id];if(!c||!d)return;let cost=d.cost;if(d.type==='Skill'&&run.hero.id==='tide'&&!run.used.flow){cost=0;run.used.flow=true;addLog('Flowing Current: first Skill is free.')}if(cost>run.energy){showToast('Not enough Energy');return}run.energy-=cost;run.hand.splice(index,1);run.discard.push(c);run.cardsPlayed++;if(d.damage){run.attackCount++;for(let h=0;h<(d.hits||1);h++){if(run.enemy.hp<=0)break;dealDamage(d.damage,true)}}if(d.block)gainBlock(d.block);if(d.strength){run.strength+=d.strength;addLog(`You gain ${d.strength} Strength.`)}if(d.heal){run.hp=Math.min(run.maxHp,run.hp+d.heal);addLog(`You recover ${d.heal} HP.`)}if(d.weaken){run.enemyStrength=Math.max(0,run.enemyStrength-d.weaken);addLog(`Enemy weakened by ${d.weaken}.`)}if(d.draw)drawCards(d.draw);if(d.type==='Skill'&&run.hero.id==='rebel'&&!run.used.sabotage){run.used.sabotage=true;drawCards(1);addLog('Sabotage draws 1 card.')}if(run.hero.id==='monkey'&&run.cardsPlayed%3===0)gainBlock(3);if(run.enemy.hp<=0){winCombat();return}renderGame()}
function endTurn(){if(run.status!=='combat')return;run.discard.push(...run.hand.splice(0));let [kind,val]=run.enemy.pattern[run.enemyStep%run.enemy.pattern.length];run.enemyStep++;if(kind==='attack'){let hit=val+run.enemyStrength;let absorbed=Math.min(run.block,hit);run.block-=absorbed;let dmg=hit-absorbed;run.hp=Math.max(0,run.hp-dmg);addLog(`${run.enemy.name} strikes for ${hit}${absorbed?`, blocked ${absorbed}`:''}.`)}else if(kind==='buff'){run.enemyStrength+=val;addLog(`${run.enemy.name} gains ${val} Strength.`)}else if(kind==='guard'){run.enemyBlock+=val;addLog(`${run.enemy.name} gains ${val} Block.`)}if(run.hp<=0){run.status='lost';renderGame();return}run.turn++;startTurn()}
function winCombat(){run.status='reward';run.victories++;if(run.hero.id==='tide')run.hp=Math.min(run.maxHp,run.hp+10);if(run.hero.id==='war')run.hp=Math.min(run.maxHp,run.hp+5);if(run.hero.id==='necro')run.hp=Math.min(run.maxHp,run.hp+5);addLog(`${run.enemy.name} defeated.`);let pool=Object.keys(CARDS).filter(id=>!run.deck.some(c=>c.id===id));run.rewards=shuffle(pool).slice(0,3);if(run.rewards.length<3)run.rewards=shuffle(Object.keys(CARDS)).slice(0,3);renderGame()}
function takeReward(id){if(id)run.deck.push({id});if(run.act===3){run.status='won'}else{run.act++;run.status='combat';run.turn=1;startCombat()}renderGame()}
function cardHtml(c,index=null){const d=CARDS[c.id];return `<div class="card ${index!==null&&d.cost>run.energy?'disabled':''}" ${index!==null?`data-card="${index}"`:''} style="--card-accent:${d.accent}"><div class="card-top"><div class="cost">${d.cost}</div><div class="card-type">${d.type}</div></div><div class="card-art">${d.icon}</div><h3>${d.name}</h3><div class="card-desc">${d.desc}</div><div class="card-tag">${d.type==='Attack'?'⚔ Strike':'✧ '+d.type}</div></div>`}
function renderGame(){if(!run)return;let h=run.hero,e=run.enemy;const hpct=e?Math.max(0,e.hp/e.maxHp*100):0;let intent='';if(e){const [k,v]=e.pattern[run.enemyStep%e.pattern.length];intent=k==='attack'?`⚔ &nbsp; Intends to strike for ${v+run.enemyStrength}`:k==='buff'?`↗ &nbsp; Gathers ${v} Strength`:`◈ &nbsp; Raises ${v} Block`}
app.innerHTML=`<main class="game-screen" style="--hero-color:${h.color}"><div class="topbar"><div class="topbar-left"><div class="run-name"><span>MYTHOS</span> &nbsp; · &nbsp; THE SHATTERED REALMS</div><div class="act-label">Encounter ${Math.min(run.act,3)} / 3</div></div><div class="top-actions"><button class="tiny-btn" data-action="perks">✧ &nbsp; Perks</button><button class="tiny-btn" data-action="restart">↻ &nbsp; New run</button></div></div><div class="combat-layout"><section class="battle-main"><div class="battle-title"><span>REALM ${run.act}</span><strong>·</strong><span>${e?.boss?'THE FINAL THRONE':'THE SHATTERED WILDS'}</span></div><div class="stage"><div class="stage-glow"></div>${e?`<div class="enemy-wrap"><div class="enemy-emoji">${e.icon}</div><div class="enemy-name">${e.name}</div><div class="enemy-sub">${e.kind}</div><div class="enemy-bar-wrap"><div class="health-meta"><span>VITALITY</span><span>${e.hp} / ${e.maxHp}</span></div><div class="health-track"><div class="health-fill" style="width:${hpct}%"></div></div><div class="intent">${intent}</div></div></div>`:''}</div><div class="combat-status">${run.strength?`<span class="status-chip gold">⚔ +${run.strength} Strength</span>`:''}${run.enemyBlock?`<span class="status-chip">◈ Enemy Block ${run.enemyBlock}</span>`:''}${run.enemyStrength?`<span class="status-chip gold">↗ Enemy Strength +${run.enemyStrength}</span>`:''}</div><div class="floor-label">✦ &nbsp; YOUR TURN — PLAY CARDS &nbsp; ✦</div><div class="hero-row"><div class="hero-portrait">${h.icon}<span class="portrait-hp">♥ ${run.hp}</span></div><div class="player-stats"><div class="stat-pill"><b>${run.block}</b><span>Block</span></div><div class="stat-pill"><b>${run.deck.length}</b><span>Deck</span></div></div></div><div class="turn-row"><div class="energy-label">✦ &nbsp; ENERGY <span class="energy-orbs">${Array.from({length:3},(_,i)=>`<i class="orb ${i>=run.energy?'empty':''}"></i>`).join('')}</span> <b>${run.energy}/3</b></div><button class="primary-btn end-turn" data-action="end">End turn&nbsp; ↗</button></div><div class="hand">${run.hand.map((c,i)=>cardHtml(c,i)).join('')||'<div class="hint">No cards in hand. End your turn to draw again.</div>'}</div></section><aside class="sidebar"><div class="side-section"><div class="side-heading">Your champion <span>LV. 01</span></div><div class="player-panel"><div class="side-avatar">${h.icon}</div><div><div class="side-name">${h.name}</div><div class="side-class">${h.title}</div></div></div><div class="side-hp"><div class="side-hp-meta"><span>♥ &nbsp; VITALITY</span><span>${run.hp} / ${run.maxHp}</span></div><div class="health-track"><div class="health-fill" style="width:${Math.max(0,run.hp/run.maxHp*100)}%"></div></div></div></div><div class="side-section"><div class="side-heading">Signature perks <span>3 / 3</span></div><div class="perk-list">${h.perks.map((p,i)=>`<div class="perk-row"><div class="perk-gem">${p[0]}</div><div class="perk-copy"><b>${p[1]}</b><span>${p[2]}</span></div></div>`).join('')}</div></div><div class="side-section"><div class="side-heading">Your relics <span>✦ ${run.victories}</span></div><div class="relics"><div class="relic" data-tip="A memory of your journey. Keep fighting.">✧</div>${run.act>1?'<div class="relic" data-tip="Victory’s mark: you survived a realm.">🏵</div>':''}${run.act>2?'<div class="relic" data-tip="The Hollow King awaits.">👑</div>':''}</div></div><div class="side-section"><div class="side-heading">Deck & discard</div><div class="deck-list"><div class="deck-item"><i>🂠</i> Draw pile <span>${run.drawPile.length}</span></div><div class="deck-item"><i>▤</i> In hand <span>${run.hand.length}</span></div><div class="deck-item"><i>▧</i> Discard <span>${run.discard.length}</span></div></div></div><div class="combat-log">${run.log.map((t,i)=>`<div class="log-line">${esc(t)}</div>`).join('')}</div></aside></div></main>`;
if(run.status==='reward')showOverlayReward();if(run.status==='won')showResult(true);if(run.status==='lost')showResult(false)}
function showOverlayReward(){const options=run.rewards.map(id=>cardHtml({id})).join('');const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<div class="modal"><div class="modal-head"><div class="eyebrow">Realm ${run.act} cleared · ${run.hp} vitality remaining</div><h2>Choose your reward</h2><p>Add one card to your deck, or move onward without one.</p></div><div class="reward-grid">${options}</div><div class="modal-foot"><span>Deck size &nbsp; ${run.deck.length} cards</span><button class="reward-skip" data-action="skip">Skip reward →</button></div></div>`;app.appendChild(overlay);overlay.querySelectorAll('.card').forEach((el,i)=>el.addEventListener('click',()=>takeReward(run.rewards[i])));overlay.querySelector('[data-action=skip]').onclick=()=>takeReward(null)}
function showResult(won){const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<div class="modal"><div class="result-icon">${won?'👑':'🕯️'}</div><div class="modal-head"><div class="eyebrow">${won?'THE REALM IS FREE':'YOUR LEGEND ENDS HERE'}</div><h2>${won?'The Hollow King falls.':'A valiant end.'}</h2><p>${won?'You conquered all three realms as '+esc(run.hero.name)+'. The Shattered Realms will remember your name.':'You reached encounter '+run.act+' with '+esc(run.hero.name)+'. The realms await your return.'}</p></div><div class="result-actions"><button class="primary-btn" data-action="restart">Play again &nbsp; →</button></div></div>`;app.appendChild(overlay)}
function showPerks(){const h=run.hero;const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<div class="modal perks-modal"><div class="modal-head"><div class="eyebrow">${h.icon} &nbsp; ${h.name}</div><h2>Your signature perks</h2><p>Three gifts that shape your path through the realms.</p></div><div class="perk-detail">${h.perks.map(p=>`<div class="perk-tile"><div class="perk-gem">${p[0]}</div><b>${p[1]}</b><p>${p[2]}</p></div>`).join('')}</div><div class="modal-foot"><span>All perks are active during this run.</span><button class="subtle-btn" data-action="close">Continue</button></div></div>`;app.appendChild(overlay)}
app.addEventListener('click',ev=>{const heroBtn=ev.target.closest('[data-hero]');if(heroBtn){selectedHero=heroBtn.dataset.hero;heroSelect();return}const card=ev.target.closest('[data-card]');if(card){playCard(Number(card.dataset.card));return}const act=ev.target.closest('[data-action]')?.dataset.action;if(!act)return;if(act==='start')startRun();if(act==='end')endTurn();if(act==='restart'){run=null;heroSelect()}if(act==='perks')showPerks();if(act==='close')document.querySelector('.overlay')?.remove();if(act==='skip')takeReward(null)});
heroSelect();

